style.css:
/* === 安全覆蓋版：無須抓特定節點，100% 會顯示 === */
:root{
  /* 換成你的圖： */
  --my-logo: url("https://i.postimg.cc/0j05THvL/Guatemala.png");
}

/* 在左側側欄頂部「覆蓋」一張圖 */
body::before{
  content:"";
  position: fixed;
  left: 14px;        /* 視需要微調，讓它貼齊側欄 */
  top: 12px;
  width: 110px;      /* 圖示寬度（可調） */
  height: 46px;      /* 圖示高度（可調） */
  background-image: var(--my-logo);
  background-repeat: no-repeat;
  background-size: contain;
  background-position: left center;
  z-index: 9999;     /* 蓋在原本圖示上 */
  pointer-events: none; /* 不擋住點擊 */
}

/* （可選）當側欄縮起來時，把位置往右靠一點 */
@media (max-width: 1024px){
  body::before{ left: 10px; top: 10px; width: 96px; height: 40px; }
}

